const body = $json.body || $json;
const headers = $json.headers || {};
const request_id = body.request_id || `req_${Date.now()}`;
const author_id = body.author_id;
const email = body.email;

if (!author_id && !email && !(body.author && body.books)) {
  return [{
    json: {
      ok: false,
      status: 'Failed',
      request_id,
      error: 'author_id or email or author+books payload required',
      skip_ai: true
    }
  }];
}

return [{
  json: {
    ok: true,
    request_id,
    author_id,
    email,
    author: body.author || null,
    books: body.books || null,
    bubble_author_unique_id: body.bubble_author_unique_id || null,
    notification_log_id: body.notification_log_id || null,
    received_at: new Date().toISOString(),
    raw_headers: headers
  }
}];

const author = $json.author;
const books = $json.books || [];
const totals = books.reduce((acc, b) => {
  acc.earned += Number(b.total_royalty_earned || 0);
  acc.paid += Number(b.royalty_paid || 0);
  acc.pending += Number(b.royalty_pending || 0);
  return acc;
}, { earned: 0, paid: 0, pending: 0 });

return [{
  json: {
    ...($json),
    author,
    books,
    totals,
    books_json: JSON.stringify(books, null, 2)
  }
}];

// Justification (README): preferred path is webhook with author_id only,
// then fetch from Bubble Data API. For offline/demo imports we also accept
// a full author+books payload. If Bubble creds are not configured, fail clearly.
const staticData = $getWorkflowStaticData('global');
if (!staticData.sampleAuthors) {
  staticData.sampleAuthors = {};
}

const author_id = $json.author_id;
const email = ($json.email || '').toLowerCase();

// Placeholder: when connected to Bubble, replace this Code node with
// HTTP Request → Bubble Data API:
// GET https://<app>.bubbleapps.io/api/1.1/obj/author?constraints=[{"key":"author_id","constraint_type":"equals","value":"AUTH001"}]
// then GET books constrained by author unique id.

return [{
  json: {
    ...$json,
    ok: false,
    status: 'Failed',
    skip_ai: true,
    error: 'No author+books in webhook body. Either send full payload from Bubble OR replace this node with Bubble Data API fetch. See n8n/README.md.'
  }
}];

