const prev = $('Use Webhook Payload').item.json;
const ai = $json;
const content = ai.choices?.[0]?.message?.content?.trim();
const failed = !content || ai.error || (ai.statusCode && ai.statusCode >= 400);

if (failed) {
  return [{
    json: {
      ...prev,
      ok: false,
      status: 'Failed',
      email_body: null,
      error_message: ai.error?.message || ai.message || 'AI API call failed',
      completed_at: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    ...prev,
    ok: true,
    status: 'Success',
    email_body: content,
    error_message: null,
    completed_at: new Date().toISOString()
  }
}];
